    # Color the remaining connected pieces according to their location.
    left = occupied - {(r, c) for r in range(h) for c in range(w) if out[r][c] == 1}
    comps = []
    while left:
        seed = min(left)
        left.remove(seed)
        comp = {seed}
        stack = [seed]
        while stack:
            r, c = stack.pop()
            for p in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if p in left:
                    left.remove(p)
                    comp.add(p)
                    stack.append(p)
        comps.append(comp)

    for comp in comps:
        minr = min(r for r, c in comp)
        minc = min(c for r, c in comp)
        color = 3 if minc == 0 else (4 if minc >= w // 2 else 2)
