def transform(grid):
    h, w = len(grid), len(grid[0])
    cells = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8}
    out = [[0] * w for _ in range(h)]

    # Exact-cover the shape with 2x2 squares and L triominoes. The examples
    # show squares in color 1; Ls are colored by their missing corner.
    pieces = []
    for r in range(h):
        for c in range(w):
            square = {(r, c), (r+1, c), (r, c+1), (r+1, c+1)}
            if all(0 <= y < h and 0 <= x < w for y, x in square):
                pieces.append((square, 1))
            box = {(r+i, c+j) for i in range(2) for j in range(2)}
            if all(0 <= y < h and 0 <= x < w for y, x in box):
                for miss in box:
                    tri = box - {miss}
                    color = {(r,c): 2, (r+1,c+1): 2, (r+1,c): 3, (r,c+1): 4}[miss]
                    pieces.append((tri, color))

    by_cell = {p: [] for p in cells}
    for shape, color in pieces:
        if shape <= cells:
            for p in shape:
                by_cell[p].append((shape, color))

    def solve(rem):
        if not rem:
            return []
        p = min(rem, key=lambda q: sum(s <= rem for s, _ in by_cell[q]))
        for shape, color in by_cell[p]:
            if shape <= rem:
                rest = solve(rem - shape)
                if rest is not None:
                    return [(shape, color)] + rest
        return None

    tiling = solve(cells)
    if tiling:
        for shape, color in tiling:
            for r, c in shape:
                out[r][c] = color
    return out
